import java.util.Scanner;

public class Main {
    static int n, k, p;
    static int[][] cache = new int[30][250005];
    static int[] factorials = new int[250005];
    static int[] invFactorials = new int[250005];

    static int binpow(int base, int exp) {
        long res = 1;
        long cur = base;
        while (exp > 0) {
            if ((exp & 1) == 1) res = (res * cur) % p;
            cur = (cur * cur) % p;
            exp >>= 1;
        }
        return (int) res;
    }

    static int getLowbit(int x) {
        return x & (-x);
    }

    static int compute(int index, int mask) {
        if (cache[index][mask] != -1)
            return cache[index][mask];
        if (mask == 0) {
            long res = factorials[n];
            for (int i = 1; i <= index; i++)
                res = (res * (k - i + 1)) % p;
            return cache[index][mask] = (int) res;
        }
        long sum = 0;
        int rem = mask - getLowbit(mask);
        for (int subset = rem; subset != 0; subset = (subset - 1) & rem)
            sum = (sum + ((long) invFactorials[mask - subset] * compute(index + 1, subset)) % p) % p;
        sum = (sum + ((long) invFactorials[mask] * compute(index + 1, 0)) % p) % p;
        return cache[index][mask] = (int) sum;
    }

    static void setup() {
        factorials[0] = 1;
        for (int i = 1; i <= n; i++)
            factorials[i] = (int) ((long) factorials[i - 1] * i % p);
        invFactorials[n] = binpow(factorials[n], p - 2);
        for (int i = n; i >= 1; i--)
            invFactorials[i - 1] = (int) ((long) invFactorials[i] * i % p);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        k = sc.nextInt();
        p = sc.nextInt();

        int total = 1;
        for (int i = 1; i <= n; i++)
            total = (int) ((long) total * k % p);

        if (n % 2 == 0) {
            for (int i = 0; i < cache.length; i++) {
                for (int j = 0; j < cache[i].length; j++) {
                    cache[i][j] = -1;
                }
            }
            setup();
            total = (total - compute(0, n) + p) % p;
        }
        System.out.println(total);
        sc.close();
    }
}
